// MSB-first (Adafruit GFX) -> LSB-first (XBM, чего ждёт u8g2.drawXBM()) для одного байта
static uint8_t reverseBits(uint8_t b) {
  b = (b & 0xF0) >> 4 | (b & 0x0F) << 4;
  b = (b & 0xCC) >> 2 | (b & 0x33) << 2;
  b = (b & 0xAA) >> 1 | (b & 0x55) << 1;
  return b;
}

// Общее для обоих способов отрисовки (полного и частичного) — чтобы кадр не "прыгал"/не
// сбрасывался при переключении между ними
static uint8_t currentFrame = 0;
static unsigned long lastFrameChange = 0;

static void advanceFrameIfDue() {
  if (millis() - lastFrameChange >= MENU_ICON_FRAME_DELAY_MS) {
    lastFrameChange = millis();
    currentFrame = (currentFrame + 1) % FRAME_COUNT;
  }
}

static void copyCurrentFrame(uint8_t* buf) {
  for (uint16_t i = 0; i < FRAME_BYTES; i++) {
    buf[i] = reverseBits(pgm_read_byte(&frames[currentFrame][i]));
  }
}

// Рисует кадр в УЖЕ ОЧИЩЕННЫЙ буфер — вызывается из drawMenu(), которая сама делает
// clearBuffer()+...+sendBuffer(). Не годится для фонового "кручения" без действий
// пользователя (см. animateDimmerIconPartial() и комментарий в .h)
void drawDimmerAnim(int x, int y) {
  advanceFrameIfDue();
  uint8_t buf[FRAME_BYTES];
  copyCurrentFrame(buf);
  u8g2.drawXBM(x, y, FRAME_WIDTH, FRAME_HEIGHT, buf);
}

// Для фонового кручения без полной перерисовки экрана — см. подробный комментарий в .h.
// Пропускает свой ход (не форсирует задержку — это чисто декоративная анимация), если
// недавно была любая другая передача на дисплей (полная перерисовка ИЛИ предыдущее
// частичное обновление), чтобы не давить на шину чаще, чем DISPLAY_REDRAW_MIN_GAP_MS
void animateDimmerIconPartial(int x, int y) {
  static unsigned long lastPartialUpdate = 0;
  unsigned long now = millis();
  unsigned long lastAnyDisplayTransfer = max(lastPartialUpdate, lastMenuDrawTime());
  if (now - lastAnyDisplayTransfer < DISPLAY_REDRAW_MIN_GAP_MS) {
    return;
  }
  lastPartialUpdate = now;

  advanceFrameIfDue();

  // drawXBM не чистит фон сам (прозрачный для нулевых бит) — без явной очистки региона
  // предыдущий кадр мог бы местами "проглядывать" через новый
  u8g2.setDrawColor(0);
  u8g2.drawBox(x, y, FRAME_WIDTH, FRAME_HEIGHT);
  u8g2.setDrawColor(1);
  uint8_t buf[FRAME_BYTES];
  copyCurrentFrame(buf);
  u8g2.drawXBM(x, y, FRAME_WIDTH, FRAME_HEIGHT, buf);

  // Переводим пиксельные координаты иконки в тайлы (1 тайл = 8x8px) и шлём по SPI
  // ТОЛЬКО их, а не весь буфер (u8g2.sendBuffer() послал бы все 1024 байта)
  uint8_t tx = x / 8;
  uint8_t tw = (x + FRAME_WIDTH - 1) / 8 - tx + 1;
  uint8_t ty = y / 8;
  uint8_t th = (y + FRAME_HEIGHT - 1) / 8 - ty + 1;
  u8g2.updateDisplayArea(tx, ty, tw, th);
  markPartialDisplayTransfer();
}
